LOW_SCALE_68_SECONDARY_RESIDUAL_LOAD_ZERO_ENDGAME_THEOREMS="$(sed -n 's/^theorem \([^ ]*\).*/Max11DegreeRoutes.\1/p' LowScale68SecondaryResidualLoadZeroEndgame.lean)"
THEOREMS="$THEOREMS $LOW_SCALE_68_SECONDARY_RESIDUAL_ROW_TWO_SYSTEM_THEOREMS $LOW_SCALE_68_SECONDARY_RESIDUAL_ROW_TWO_FACES_THEOREMS $LOW_SCALE_68_SECONDARY_RESIDUAL_ROW_TWO_BALANCED_THEOREMS $LOW_SCALE_68_SECONDARY_RESIDUAL_BALANCED_SELECTOR_THEOREMS $LOW_SCALE_68_SECONDARY_RESIDUAL_CANONICAL_BALANCED_THEOREMS $LOW_SCALE_68_SECONDARY_RESIDUAL_CANONICAL_BALANCED_DATA_THEOREMS $LOW_SCALE_68_SECONDARY_RESIDUAL_ROW_ONE_FACES_THEOREMS $LOW_SCALE_68_SECONDARY_RESIDUAL_ROW_ONE_SYSTEM_THEOREMS $LOW_SCALE_68_SECONDARY_RESIDUAL_BALANCED_ENDGAME_THEOREMS $LOW_SCALE_68_SECONDARY_RESIDUAL_LOAD_ZERO_ENDGAME_THEOREMS"
PROBE="${PROBE}import LowScale68SecondaryResidualRowTwoSystem\n"
