RECENT_MODULES="LowScale410NormalForm LowScale410FirstIntegrals LowScale410ZeroLoadTrajectory LowScale410ZeroLoadShiftedFiber LowScale410LoadCascade LowScale410LWall LowScale410LWallBoundary LowScale410LWallResidual LowScale410LWallOtherCones LowScale410LWallFanConnector LowScale410LWallUnconditional LowScale410ScaleTwoSourceFace LowScale610ScaleTwoSourceFace LowScale810ScaleTwoSourceFace LowScale68ScaleZeroAssembly LowScale68ScaleTwoSourceFace LowScale68ScaleTwoNonalignedInfinity LowScale68ScaleTwoLocalInitialForms LowScale68ScaleTwoLocalRowThree LowScale68ScaleTwoLocalDerivativeRowTwo LowScale68ScaleTwoIntegratedBoundary LowScale68ScaleTwoLocalRowOneZero LowScale68ScaleTwoLocalRhoFour LowScale68ScaleTwoLocalRhoThree LowScale68ScaleTwoLocalRhoTwo LowScale68ScaleTwoAfterRhoTwo LowScale68ScaleTwoLocalRhoOne LowScale68ScaleTwoRhoOneTransverse LowScale68ScaleTwoRhoOneComponentSplit LowScale68ScaleTwoRhoOneNoncubicNext LowScale68ScaleTwoRhoOneNoncubicElimination LowScale68ScaleTwoAfterRhoOne LowScale68ScaleTwoAfterRhoOneNextBox LowScale68ScaleTwoAfterRhoOneBranchRows LowScaleRemainingShear LowScale68SecondaryLargeGapAlphaCancellation LowScale68SecondaryAlphaWallEndgame LowScale68SecondaryAlphaWallRowOneLoad LowScale68SecondaryAlphaWallRowTwoLoad LowScale68SecondaryAlphaWallMixedEndgame LowScale68SecondaryAlphaWallBalancedRowZero LowScale68SecondaryDeepGapCascade LowScale68SecondaryDeepGapResidualOneForms LowScale68SecondaryDeepGapResidualEndgame LowScale68SecondaryDeepGapMiddleBetaEndgame LowScale68SecondaryDeepGapMiddleBetaNextOrder LowScale68SecondaryDeepGapMiddleRightEndgame LowScale68SecondaryLaterDeepLoadCascade LowScale68SecondaryLaterDeepLowerEndgame LowScale68SecondaryLaterDeepLowerResidual LowScale68SecondaryLaterDeepThreeRadiusWallNext LowScale68SecondaryLaterDeepThreeRadiusWallElimination LowScale68SecondaryLaterDeepThreeRadiusResidualEntry LowScale68SecondaryLaterDeepMixedTwoNFace LowScale68SecondaryLaterDeepClampedEndgame LowScale68SecondaryLaterDeepPreclampedEndgame LowScale68SecondaryLaterDeepPreclampedLowerEndgame LowScale68SecondaryLaterDeepSixToSevenLowerCoefficient LowScale68SecondaryLaterDeepSevenBoundaryEndgame LowScale68SecondaryLaterDeepFiveToSixEndgame LowScale68SecondaryLaterDeepFiveToSixRowOne LowScale68SecondaryLaterDeepFiveToSixLowerCoefficient LowScale68SecondaryLaterDeepFiveToSixResidualNext LowScale68SecondaryLaterDeepFiveToSixNonzeroEdge LowScale68SecondaryLaterDeepFiveToSixStrideDescent"
for module in $RECENT_MODULES; do
  MODULE_THEOREMS="$(sed -n 's/^theorem \([^ ]*\).*/Max11DegreeRoutes.\1/p' "${module}.lean")"
  THEOREMS="$THEOREMS $MODULE_THEOREMS"
  PROBE="${PROBE}import ${module}\n"
done
for thm in $THEOREMS; do
  PROBE="${PROBE}#print axioms ${thm}\n"
done

OUT="$(printf '%b' "$PROBE" | lake env lean --stdin 2>&1)" || {
  echo "$OUT"
  echo "FAIL: could not elaborate the axiom probe (build first: lake build)"
  exit 1
}
echo "$OUT"

for thm in $THEOREMS; do
  if echo "$OUT" | grep -Fq "'$thm' does not depend on any axioms"; then
    continue
  fi
  BLOCK="$(echo "$OUT" | sed -n "/'$thm' depends on axioms/,/]/p" | head -20)"
  if [ -z "$BLOCK" ]; then
    echo "FAIL: no axiom report for $thm"
    exit 1
  fi
  BAD="$(echo "$BLOCK" | tr '\n' ' ' | sed -e 's/.*axioms: \[//' -e 's/\].*//' -e 's/,/\n/g' \
    | tr -d ' ' | grep -v -E '^(propext|Classical\.choice|Quot\.sound)$' || true)"
  if [ -n "$BAD" ]; then
    echo "FAIL: $thm depends on non-permitted axioms: $BAD"
    exit 1
  fi
done
COUNT="$(printf '%s\n' $THEOREMS | wc -l | tr -d ' ')"
echo "OK: all $COUNT max11-partial-y theorems use only permitted axioms."
